/// PROTO_TILE: one row per tile id (§15.2).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct TileProtos {
    /// tiles.kappa_per_s (0 when null)
    pub kappa_per_s: Vec<f64>,
    /// tiles.kappa_per_s is not null
    pub has_kappa: Vec<bool>,
    /// tiles.walking_speed (0 when null)
    pub walking_speed: Vec<f64>,
    /// tiles.walking_speed is not null
    pub walkable: Vec<bool>,
    /// tiles.buildable
    pub buildable: Vec<bool>,
    /// tiles.map_color (0xRRGGBB)
    pub map_color: Vec<u32>,
    /// tiles.placed_by (optional)
    pub placed_by: Vec<ItemId>,
    /// tiles.minable_back
    pub minable_back: Vec<bool>,
    /// tiles.town
    pub town: Vec<bool>,
    /// tiles.biome
    pub biomes: Vec<Biomes>,
    /// tiles.placed_on
    pub placed_on: ListColumn<TileId>,
    /// The number of rows, kept apart from the columns: a table may have none (C1b-r1 finding 9).
    row_count: usize,
}

impl TileProtos {
    /// The columns in file order (a list column is `_off` and `_count`): name, §8.1 type code, width.
    pub const COLUMNS: [(&'static str, u8, usize); 12] = [
        ("kappa_per_s", 10u8, 8usize),
        ("has_kappa", 11u8, 1usize),
        ("walking_speed", 10u8, 8usize),
        ("walkable", 11u8, 1usize),
        ("buildable", 11u8, 1usize),
        ("map_color", 3u8, 4usize),
        ("placed_by", 2u8, 2usize),
        ("minable_back", 11u8, 1usize),
        ("town", 11u8, 1usize),
        ("biomes", 1u8, 1usize),
        ("placed_on_off", 3u8, 4usize),
        ("placed_on_count", 2u8, 2usize),
    ];

    /// The number of rows (dense ids).
    pub fn len(&self) -> usize {
        self.row_count
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    fn read(data: &[u8], base: usize, cx: &ProtoCtx<'_>) -> DResult<Self> {
        let (rows, cols) = columns(data, base, "tile", &Self::COLUMNS)?;
        if rows != cx.rows(ProtoKind::Tile) {
            return Err(DecodeError { kind: ErrorKind::BadCount, field: "tile", at: base });
        }
        let mut t = Self { row_count: rows, ..Self::default() };
        {
            let mut c = Reader::with_base(&data[cols[0].0..cols[0].0 + cols[0].1], base + cols[0].0);
            for row in 0..rows {
                let at = c.pos();
                let v = f64::read(&mut c, "tile.kappa_per_s")?;
                let _ = at;
                t.kappa_per_s.push(v);
                let _ = row;
            }
        }
        {
            let mut c = Reader::with_base(&data[cols[1].0..cols[1].0 + cols[1].1], base + cols[1].0);
            for row in 0..rows {
                let at = c.pos();
                let v = bool::read(&mut c, "tile.has_kappa")?;
                let _ = at;
                t.has_kappa.push(v);
                let _ = row;
            }
        }
        {
            let mut c = Reader::with_base(&data[cols[2].0..cols[2].0 + cols[2].1], base + cols[2].0);
            for row in 0..rows {
                let at = c.pos();
                let v = f64::read(&mut c, "tile.walking_speed")?;
                let _ = at;
                t.walking_speed.push(v);
                let _ = row;
            }
        }
        {
            let mut c = Reader::with_base(&data[cols[3].0..cols[3].0 + cols[3].1], base + cols[3].0);
            for row in 0..rows {
                let at = c.pos();
                let v = bool::read(&mut c, "tile.walkable")?;
                let _ = at;
                t.walkable.push(v);
                let _ = row;
            }
        }
        {
            let mut c = Reader::with_base(&data[cols[4].0..cols[4].0 + cols[4].1], base + cols[4].0);
            for row in 0..rows {
                let at = c.pos();
                let v = bool::read(&mut c, "tile.buildable")?;
                let _ = at;
                t.buildable.push(v);
                let _ = row;
            }
        }
        {
            let mut c = Reader::with_base(&data[cols[5].0..cols[5].0 + cols[5].1], base + cols[5].0);
            for row in 0..rows {
                let at = c.pos();
                let v = u32::read(&mut c, "tile.map_color")?;
                let _ = at;
                t.map_color.push(v);
                let _ = row;
            }
        }
        {
            let mut c = Reader::with_base(&data[cols[6].0..cols[6].0 + cols[6].1], base + cols[6].0);
            for row in 0..rows {
                let at = c.pos();
                let v = ItemId::read(&mut c, "tile.placed_by")?;
                if !v.is_none() && usize::from(v.0) >= cx.rows(ProtoKind::Item) {
                    return Err(DecodeError { kind: ErrorKind::BadRef, field: "tile.placed_by", at });
                }
                t.placed_by.push(v);
                let _ = row;
            }
        }
        {
            let mut c = Reader::with_base(&data[cols[7].0..cols[7].0 + cols[7].1], base + cols[7].0);
            for row in 0..rows {
                let at = c.pos();
                let v = bool::read(&mut c, "tile.minable_back")?;
                let _ = at;
                t.minable_back.push(v);
                let _ = row;
            }
        }
        {
            let mut c = Reader::with_base(&data[cols[8].0..cols[8].0 + cols[8].1], base + cols[8].0);
            for row in 0..rows {
                let at = c.pos();
                let v = bool::read(&mut c, "tile.town")?;
                let _ = at;
                t.town.push(v);
                let _ = row;
            }
        }
        {
            let mut c = Reader::with_base(&data[cols[9].0..cols[9].0 + cols[9].1], base + cols[9].0);
            for row in 0..rows {
                let at = c.pos();
                let v = Biomes::read(&mut c, "tile.biomes")?;
                let _ = at;
                t.biomes.push(v);
                let _ = row;
            }
        }
        let mut placed_on_off = Vec::with_capacity(rows);
        {
            let mut c = Reader::with_base(&data[cols[10].0..cols[10].0 + cols[10].1], base + cols[10].0);
            for _ in 0..rows {
                placed_on_off.push(c.u32("tile.placed_on_off")?);
            }
        }
        {
            let mut c = Reader::with_base(&data[cols[11].0..cols[11].0 + cols[11].1], base + cols[11].0);
            for row in 0..rows {
                let at = c.pos();
                let n = c.u16("tile.placed_on_count")?;
                let mut l = cx.list(placed_on_off[row], n, 1, "tile.placed_on_count", at)?;
                let a = t.placed_on.items.len() as u32;
                for _ in 0..n {
                    let v = TileId::read(&mut l, "tile.placed_on_count")?;
                    if usize::from(v.0) >= cx.rows(ProtoKind::Tile) {
                        return Err(DecodeError {
                            kind: ErrorKind::BadRef,
                            field: "tile.placed_on_count",
                            at: l.pos(),
                        });
                    }
                    t.placed_on.items.push(v);
                }
                t.placed_on.ranges.push((a, t.placed_on.items.len() as u32));
            }
        }
        Ok(t)
    }
}

