/// The name tables (NAMES, §15.2): each kind's names in id order, for saves (§8.3), well-known names
/// and debugging.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ProtoNames {
    pub item: Vec<String>,
    pub fluid: Vec<String>,
    pub recipe: Vec<String>,
    pub entity: Vec<String>,
    pub technology: Vec<String>,
    pub resource: Vec<String>,
    pub tile: Vec<String>,
    pub world_object: Vec<String>,
    pub signal: Vec<String>,
}

impl ProtoNames {
    pub fn of(&self, k: ProtoKind) -> &[String] {
        match k {
            ProtoKind::Item => &self.item,
            ProtoKind::Fluid => &self.fluid,
            ProtoKind::Recipe => &self.recipe,
            ProtoKind::Entity => &self.entity,
            ProtoKind::Technology => &self.technology,
            ProtoKind::Resource => &self.resource,
            ProtoKind::Tile => &self.tile,
            ProtoKind::WorldObject => &self.world_object,
            ProtoKind::Signal => &self.signal,
        }
    }
    /// The id of a name.
    pub fn find(&self, k: ProtoKind, name: &str) -> Option<u16> {
        self.of(k).iter().position(|n| n == name).map(|i| i as u16)
    }
}

/// The ids of the names the engine must know (registries.yaml `well_known`), when the build has them.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct WellKnownIds {
    pub character: Option<EntityId>,
}

/// prototypes.bin, loaded (§15.2): the sim's tables, indexed by dense id.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Protos {
    pub item: ItemProtos,
    pub fluid: FluidProtos,
    pub recipe: RecipeProtos,
    pub entity: EntityProtos,
    pub technology: TechnologyProtos,
    pub resource: ResourceProtos,
    pub tile: TileProtos,
    pub world_object: WorldObjectProtos,
    pub signal: SignalProtos,
    /// The EXPR section: programs at the offsets ExprRefs hold.
    pub expr: Vec<u8>,
    pub start: MetaStart,
    pub contents: MetaContents,
    pub names: ProtoNames,
    pub well_known: WellKnownIds,
}

impl Protos {
    /// Loads prototypes.bin and refuses a malformed file (ERR_PROTOS, §15.2): a wrong magic, version or
    /// schema hash; sections other than PROTOS_SECTIONS in order, or not raw; a column table whose
    /// directory differs from the schema; an enum, flag, bool or NaN that does not decode; an id outside its
    /// kind's rows; an ExprRef that is not a program start, or whose program uses more variables than its
    /// formula field has; a malformed program; a list outside LISTS; META records other than the schema's,
    /// or a contents record that omits a block this engine reads (capabilities.rs REQUIRED_DATA, C1a-r1
    /// finding 5); a name table that does not match its kind's rows.
    pub fn load(bytes: &[u8]) -> DResult<Self> {
        let mut r = Reader::new(bytes);
        let h = ProtosHeader::read(&mut r, "ProtosHeader")?;
        if h.magic != PROTOS_MAGIC {
            return Err(r.err_at(0, ErrorKind::BadMagic, "ProtosHeader.magic"));
        }
        if h.format_version != PROTOS_FORMAT_VERSION {
            return Err(r.err_at(8, ErrorKind::BadVersion, "ProtosHeader.format_version"));
        }
        if h.schema_hash.bytes != crate::SCHEMA_HASH {
            return Err(r.err_at(12, ErrorKind::SchemaMismatch, "ProtosHeader.schema_hash"));
        }
        if h.data_version != PROTOS_DATA_VERSION {
            return Err(r.err_at(44, ErrorKind::BadVersion, "ProtosHeader.data_version"));
        }
        if h.section_count as usize != PROTOS_SECTIONS.len() {
            return Err(r.err_at(48, ErrorKind::BadCount, "ProtosHeader.section_count"));
        }
        let mut data: [&[u8]; 13] = [&[]; 13];
        let mut bases = [0usize; 13];
        for (i, want) in PROTOS_SECTIONS.iter().enumerate() {
            let at = r.pos();
            let f = SectionFrame::decode(&mut r)?;
            if f.id != *want {
                return Err(r.err_at(at, ErrorKind::UnknownType, "SectionFrame.id"));
            }
            if f.version != PROTOS_SECTION_VERSION {
                return Err(r.err_at(at + 4, ErrorKind::BadVersion, "SectionFrame.version"));
            }
            if f.codec != SectionCodec::Raw
                || f.flags != SectionFlags::EMPTY
                || f.raw_length as usize != f.data.len()
            {
                return Err(r.err_at(at + 6, ErrorKind::NotCanonical, "SectionFrame.codec"));
            }
            data[i] = f.data;
            bases[i] = at + 16;
        }
        r.finish("prototypes.bin")?;
        let expr = data[11];
        let starts = expr_programs(expr).map_err(|(at, why)| DecodeError {
            kind: ErrorKind::BadEnum,
            field: why,
            at: bases[11] + at,
        })?;
        let mut rows = [0usize; 9];
        rows[ProtoKind::Item.value() as usize] = table_rows(data[0], bases[0])?;
        rows[ProtoKind::Fluid.value() as usize] = table_rows(data[1], bases[1])?;
        rows[ProtoKind::Recipe.value() as usize] = table_rows(data[2], bases[2])?;
        rows[ProtoKind::Entity.value() as usize] = table_rows(data[3], bases[3])?;
        rows[ProtoKind::Technology.value() as usize] = table_rows(data[4], bases[4])?;
        rows[ProtoKind::Resource.value() as usize] = table_rows(data[5], bases[5])?;
        rows[ProtoKind::Tile.value() as usize] = table_rows(data[6], bases[6])?;
        rows[ProtoKind::WorldObject.value() as usize] = table_rows(data[7], bases[7])?;
        rows[ProtoKind::Signal.value() as usize] = table_rows(data[8], bases[8])?;
        let cx = ProtoCtx { rows, lists: data[9], lists_base: bases[9], expr, starts };
        let item = ItemProtos::read(data[0], bases[0], &cx)?;
        let fluid = FluidProtos::read(data[1], bases[1], &cx)?;
        let recipe = RecipeProtos::read(data[2], bases[2], &cx)?;
        let entity = EntityProtos::read(data[3], bases[3], &cx)?;
        let technology = TechnologyProtos::read(data[4], bases[4], &cx)?;
        let resource = ResourceProtos::read(data[5], bases[5], &cx)?;
        let tile = TileProtos::read(data[6], bases[6], &cx)?;
        let world_object = WorldObjectProtos::read(data[7], bases[7], &cx)?;
        let signal = SignalProtos::read(data[8], bases[8], &cx)?;
        // META: u32 count, then per record u16 type and the record, ascending by type, each once.
        let mut m = Reader::with_base(data[10], bases[10]);
        let count = m.u32("META")?;
        if count as usize != 2 {
            return Err(m.err(ErrorKind::BadCount, "META"));
        }
        let at = m.pos();
        if m.u16("META")? != 1 {
            return Err(m.err_at(at, ErrorKind::UnknownType, "META"));
        }
        let start = MetaStart::decode(&mut m, true)?;
        let at = m.pos();
        if m.u16("META")? != 2 {
            return Err(m.err_at(at, ErrorKind::UnknownType, "META"));
        }
        let contents = MetaContents::decode(&mut m, true)?;
        m.finish("META")?;
        let carried = &contents;
        for block in crate::capabilities::REQUIRED_DATA {
            if !carried.meta.iter().any(|b| b == block) || carried.omitted.iter().any(|b| b == block) {
                return Err(DecodeError { kind: ErrorKind::MissingField, field: block, at: bases[10] });
            }
        }
        // NAMES: per kind in ProtoKind order, u16 count (the kind's rows), then each name.
        let mut nr = Reader::with_base(data[12], bases[12]);
        let mut names = ProtoNames::default();
        for k in ProtoKind::ALL {
            let at = nr.pos();
            let n = usize::from(nr.u16("NAMES")?);
            if n != cx.rows(k) {
                return Err(nr.err_at(at, ErrorKind::BadCount, "NAMES"));
            }
            let mut list = Vec::with_capacity(n);
            for _ in 0..n {
                let at = nr.pos();
                let s = nr.str16(255, "NAMES")?;
                if s.is_empty() || list.iter().any(|x: &String| x == s) {
                    return Err(nr.err_at(at, ErrorKind::NotCanonical, "NAMES"));
                }
                list.push(s.to_owned());
            }
            match k {
                ProtoKind::Item => names.item = list,
                ProtoKind::Fluid => names.fluid = list,
                ProtoKind::Recipe => names.recipe = list,
                ProtoKind::Entity => names.entity = list,
                ProtoKind::Technology => names.technology = list,
                ProtoKind::Resource => names.resource = list,
                ProtoKind::Tile => names.tile = list,
                ProtoKind::WorldObject => names.world_object = list,
                ProtoKind::Signal => names.signal = list,
            }
        }
        nr.finish("NAMES")?;
        let well_known = WellKnownIds { character: names.find(ProtoKind::Entity, "character").map(EntityId) };
        Ok(Self {
            item,
            fluid,
            recipe,
            entity,
            technology,
            resource,
            tile,
            world_object,
            signal,
            expr: expr.to_vec(),
            start,
            contents,
            names,
            well_known,
        })
    }

    /// The program an ExprRef names (validated by load), or None.
    pub fn program(&self, e: ExprRef) -> Option<&[u8]> {
        if e.is_none() {
            return None;
        }
        let at = e.0 as usize;
        let n = usize::from(u16::from_le_bytes([*self.expr.get(at)?, *self.expr.get(at + 1)?]));
        self.expr.get(at..at + 4 + n)
    }
}

/// A column table's row count (its first u32).
fn table_rows(data: &[u8], base: usize) -> DResult<usize> {
    Ok(Reader::with_base(data, base).u32("rows")? as usize)
}
